    choose: [['Her words were taken out (of / from) context.', 'of'], ['The title gives a misleading (impression / impress).', 'impression'], ['Attention must not come at the (expense / expensive) of accuracy.', 'expense'], ['We should put the record (straight / straightly).', 'straight'], ['I am concerned (that / what) the title overstates the evidence.', 'that'], ['Could we (restore / restored) the missing context?', 'restore']],
