export const beyondWorkshopId = (number: StoryLessonNumber) => `conversational-skills-L6-C2-${number}-${beyondWorkshopEpisodes[number].skill}-en-v1`;

export function buildBeyondWorkshopLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildEnglishExpressionLesson(number, beyondWorkshopEpisodes[number], previous, reference, {
    id: beyondWorkshopId(number), chapterName: 'Beyond the Workshop', pronunciation: naturalPronunciationLessons[2][number],
    setting: 'A fictional documentary journey from Kanazawa to Echizen Washi Village in Fukui, Takayama and Gujo Hachiman in Gifu, then back to Kanazawa. Real craft and festival backgrounds support fictional characters, interviews and screening arrangements.',
    previousSummary: index === 0 ? traditionsEpisodes[9].closing : beyondWorkshopEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: `${conversationalLanguageInstructions(6)}\nReference: Beyond the Workshop. Eight story episodes map to 1-4 and 6-9; 5/10 remain dynamic checkpoints. Follow the saved authoring corrections: objective before situation, plain situation fields, separate structured questions, direct roles and natural tutor-first dialogue. Four English expressions with meanings, highlighted examples and stress/rhythm practice. English only, no new artwork, no romance. Preserve the festival success without inventing release of the earlier film. New invitation and shared roles are not a signed paid contract. Papermaking is supervised partial beginner practice, not a full production manual. Yui’s catalogue is an idea, not a launched service; her conditional portrayal request and independent choices matter. Woodwork and dyeing share experienced judgment, not identical methods; machines and hand tools can complement one another. Fivefold tray price is specific to the fictional pair, not a universal claim. Affordability and sustainable maker income both matter. Gujo Odori occurs in summer; do not invent calendar dates, blanket filming permission or a universal participant motive. Keep Yui’s contextual correction and both film titles. Agreed verification and sensitive-section reviews are not already-completed approvals. A warm community screening and one student’s response do not prove universal impact or economic preservation. Future documentary suggestions do not confirm a sequel, route, dates or budget.`,
  });
  lesson.storyData.storyTitle = 'Threads of Tradition';
  lesson.storyData.characters = [
    { id: 'aiko', name: 'Aiko', role: 'main', description: 'Museum educator based in Tokyo. She researches craft history and asks whether the documentary’s claims match the evidence.' },
    { id: 'haru', name: 'Haru', role: 'supporting', description: 'Kanazawa family-workshop member. He compares craft knowledge and recognises both maker livelihoods and buyer budgets.' },
    { id: 'mei', name: 'Mei', role: 'supporting', description: 'Chef from Kyoto. She explores food interests, joins activities enthusiastically and notices missing context in Yui’s edit.' },
    { id: 'daniel', name: 'Daniel', role: 'supporting', description: 'Canadian photographer living in Japan. He leads the documentary and learns to question his framing and assumptions.' },
    { id: 'takeda', name: 'Mrs. Takeda', role: 'supporting', description: 'Haru’s grandmother and Kaga Yuzen artisan. She advises focusing on people keeping traditions alive and later attends the screening.' },
    { id: 'fujita', name: 'Ms. Fujita', role: 'supporting', description: 'Fictional Echizen paper artisan with thirty years of practice. She explains purpose, experience and judgment.' },
    { id: 'yui', name: 'Yui', role: 'supporting', description: 'Ms. Fujita’s daughter, a computer-science student. She values her family’s work and considers an online catalogue while choosing her own path.' },
    { id: 'mori', name: 'Mr. Mori', role: 'supporting', description: 'Fictional Takayama woodworker. He demonstrates a wooden joint and explains the complementary use of tools and judgment.' },
  ];
  return { ...lesson, course: 'conversational-skills', level: 6, chapter: 2, lessonNumber: number,
    levelBadge: 'INTERMEDIATE', chapterLabel: 'Chapter 2: Beyond the Workshop', status: previous.status || 'draft',
    overlayColor: previous.overlayColor || '#17252bcc', supportLanguage: 'en', authoringLanguageTarget: 'TOEIC 550-780', authoringLanguageRevision: 'toeic-v1' };
}

export function buildBeyondWorkshopChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildBeyondWorkshopLesson(number, {}, reference));
}
